mapper.select:
SELECT u.id, u.nick_name AS nickName, u.avatar, COALESCE(uc.unread_count, 0) AS unreadCount, lm.content, lm.create_time AS createTime FROM `user` u LEFT JOIN ( SELECT `from` AS chat_partner_id, COUNT(id) AS unread_count FROM message WHERE `to` = #{currentUserId} AND is_read = 0 GROUP BY `from` ) uc ON u.id = uc.chat_partner_id LEFT JOIN ( SELECT m.content, m.create_time, CASE WHEN m.`from` = #{currentUserId} THEN m.`to` ELSE m.`from` END AS chat_partner_id FROM ( SELECT id, `from`, `to`, content, create_time, ROW_NUMBER() OVER ( PARTITION BY CASE WHEN `from` = #{currentUserId} THEN `to` ELSE `from` END ORDER BY create_time DESC, id DESC ) as rn FROM message WHERE `from` = #{currentUserId} OR `to` = #{currentUserId} ) m WHERE m.rn = 1 ) lm ON u.id = lm.chat_partner_id WHERE u.id IN
#{chatUserId}
ORDER BY lm.create_time DESC, u.id DESC;
